  font-size: 1.75rem;
  margin: 0 0 0.5rem;
  letter-spacing: -0.01em;
}

.subtitle {
  color: var(--muted);
  margin: 0 0 2rem;
}

.quiz-form {
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

.form-field {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 1.25rem 1.25rem 1rem;
}

.form-field legend {
  font-weight: 600;
  font-size: 1.05rem;
  padding: 0;
  margin-bottom: 0.25rem;
}

.form-field fieldset {
  border: 0;
  margin: 0;
  padding: 0;
}

.help-text {
  color: var(--muted);
  font-size: 0.9rem;
  margin: 0.25rem 0 0.75rem;
}

.choices {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  margin-top: 0.75rem;
}

.choice {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.65rem 0.85rem;
  background: var(--panel-2);
  border: 1px solid var(--border);
  border-radius: 8px;
  cursor: pointer;
  transition: border-color 120ms ease, background-color 120ms ease;
}

.choice:hover {
  border-color: var(--border-strong);
  background: #222a3a;
}

.choice input[type="checkbox"] {
  width: 18px;
  height: 18px;
  accent-color: var(--accent-strong);
  cursor: pointer;
  margin: 0;
  flex-shrink: 0;
}

.choice input[type="checkbox"]:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}

.choice:has(input[type="checkbox"]:checked) {
  border-color: var(--accent);
  background: #1f2a44;
}

.choice-label {
  user-select: none;
}

.actions {
  display: flex;
  align-items: center;
  gap: 1rem;
  margin-top: 0.5rem;
}

button[type="submit"] {
  background: var(--accent-strong);
  color: #fff;
  border: 1px solid transparent;
  border-radius: 8px;
  font-size: 1rem;
  font-weight: 600;
  padding: 0.7rem 1.4rem;
  cursor: pointer;
  transition: background-color 120ms ease, transform 80ms ease;
}

button[type="submit"]:hover { background: #6a8dff; }
button[type="submit"]:active { transform: translateY(1px); }
button[type="submit"]:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}

.result {
  margin: 0;
  font-weight: 500;
}

.result[data-state="success"] { color: var(--success); }
.result[data-state="partial"] { color: var(--focus); }
.result[data-state="error"] { color: var(--error); }

